window.openAddSupplierModal=function(){document.getElementById("supplierModalTitle").innerHTML='<i class="bi bi-building-add me-2" style="color: var(--gb-yellow);"></i>Add New Supplier',document.getElementById("supplierFormAction").value="add_supplier",document.getElementById("supplierId").value="";const randomNum=Math.floor(Math.random()*9e3+1e3);document.getElementById("supplierCode").value="SUP-"+randomNum,document.getElementById("supplierCompany").value="",document.getElementById("supplierContactPerson").value="",document.getElementById("supplierContactNumber").value="",document.getElementById("supplierEmail").value="",document.getElementById("supplierAddress").value="",document.getElementById("supplierStatus").value="Active"},window.openEditSupplierModal=function(id,code,company,person,number,email,address,status){document.getElementById("supplierModalTitle").innerHTML='<i class="bi bi-pencil-square me-2" style="color: var(--gb-yellow);"></i>Edit Supplier',document.getElementById("supplierFormAction").value="edit_supplier",document.getElementById("supplierId").value=id,document.getElementById("supplierCode").value=code,document.getElementById("supplierCompany").value=company,document.getElementById("supplierContactPerson").value=person,document.getElementById("supplierContactNumber").value=number,document.getElementById("supplierEmail").value=email,document.getElementById("supplierAddress").value=address,document.getElementById("supplierStatus").value=status};
